-- Generated by Supabase CLI 2.121.0 migration new official_milestone_monitoring.
-- No source activation, calendar capability, email delivery or new secrets.
-- Four bounded official routes have a separate lease budget so core/social cannot starve them.
create function tracker_private.lease_due_official_sources(p_limit integer,p_lease_seconds integer)
returns setof public.sources language plpgsql security definer set search_path='' as $$
declare v_source public.sources; v_now timestamptz:=clock_timestamp(); v_slot timestamptz;
begin
  if p_limit is null or p_limit not between 1 and 4
    or p_lease_seconds is null or p_lease_seconds not between 30 and 1800 then raise exception 'Invalid lease limits'; end if;
  for v_source in
    select * from public.sources
    where enabled and ((id in ('fsu-onf-dates','fsu-cre-applications','fsu-career-deadlines') and adapter='official-deadlines-v1')
      or (id='fsu-opening-nights' and adapter='official-tickets-v1'))
      and greatest(coalesce(next_poll_at,tracker_private.poll_slot_at(cadence_seconds,coalesce(next_due_at,v_now))),retry_not_before)<=v_now
      and (lease_until is null or lease_until<=v_now)
    order by greatest(coalesce(next_poll_at,tracker_private.poll_slot_at(cadence_seconds,coalesce(next_due_at,v_now))),retry_not_before),id
    for update skip locked limit p_limit
  loop
    if v_source.lease_token is not null then
      insert into public.source_runs(owner_id,source_id,started_at,finished_at,outcome,pagination_complete,parser_version,request_count,byte_count,opportunity_count,occurrence_count,cursor_before,error,scheduled_poll_at)
        values(v_source.owner_id,v_source.id,coalesce(v_source.last_attempt_at,v_now),v_now,'failed',false,'lease-recovery-v3',0,0,0,0,v_source.cursor,'Previous collector lease expired before completion; request/byte costs unknown.',v_source.leased_poll_at);
    end if;
    v_slot:=greatest(tracker_private.poll_slot_at(v_source.cadence_seconds,coalesce(v_source.next_poll_at,v_source.next_due_at,v_now)),tracker_private.poll_slot_at(v_source.cadence_seconds,v_now));
    update public.sources set next_poll_at=tracker_private.poll_slot_at(cadence_seconds,coalesce(next_poll_at,next_due_at,v_now)),
      leased_poll_at=v_slot,lease_token=gen_random_uuid(),lease_until=v_now+make_interval(secs=>p_lease_seconds),last_attempt_at=v_now,updated_at=v_now,
      consecutive_failures=case when v_source.lease_token is not null then consecutive_failures+1 else consecutive_failures end,
      health_status=case when v_source.lease_token is not null then 'failed' else health_status end,
      health_message=case when v_source.lease_token is not null then 'Retrying expired collector lease; previous attempt did not complete' else health_message end
    where id=v_source.id returning * into v_source;
    return next v_source;
  end loop;
end $$;
revoke all on function tracker_private.lease_due_official_sources(integer,integer) from public,anon,authenticated,service_role;
create function public.lease_due_official_sources(p_limit integer default 4,p_lease_seconds integer default 600)
returns setof public.sources language sql security definer set search_path='' as $$
  select * from tracker_private.lease_due_official_sources(p_limit,p_lease_seconds);
$$;
revoke all on function public.lease_due_official_sources(integer,integer) from public,anon,authenticated;
grant execute on function public.lease_due_official_sources(integer,integer) to service_role;

-- Invoker joins retain owner policies on every relation, including version metadata.
create view public.milestone_inbox with (security_invoker=true) as
select m.id,m.owner_id,m.source_id,m.opportunity_id,m.native_id,m.kind,m.occurs_at,m.occurs_on,
  coalesce(m.occurs_on,(m.occurs_at at time zone 'America/New_York')::date) as sort_date,
  m.availability,m.action_url,m.uncertainty,m.revision,
  o.title,o.description,o.source_url,o.categories,o.uncertainties,
  s.name as source_name,s.health_status,s.health_message,s.last_success_at,s.last_attempt_at,s.cadence_seconds,s.coverage_note,
  v.observed_at as changed_at,v.facts->>'source_local_text' as source_local_text,v.facts->>'timezone' as timezone
from public.milestones m join public.opportunities o on o.id=m.opportunity_id and o.owner_id=m.owner_id
join public.sources s on s.id=m.source_id and s.owner_id=m.owner_id
left join public.entity_versions v on v.milestone_id=m.id and v.content_sha256=m.content_sha256;
revoke all on public.milestone_inbox from public,anon,authenticated;
grant select on public.milestone_inbox to authenticated,service_role;
create index milestones_owner_date on public.milestones(owner_id,occurs_on,occurs_at,id);
